'use client';

/**
 * @file fieldParts.ts
 * @input Uses BaseProps, FormLayoutContext, InputGroupContext, useDevWarning
 * @output Exports FieldInputBaseProps, the container and control part style
 *   props, and useFieldInputStyling
 * @position Shared styling contract for every Field-composed input
 *   (family:input-fields FR10): base props reach the primary semantic control,
 *   there is no root `xstyle`/`className`/`style`, `container*` styles the Field
 *   box where one renders, and `control*` styles the visual control box.
 *
 * SYNC: When modified, update:
 * - /packages/core/src/Field/fieldInputFamily.test.tsx (family registry and type checks)
 * - /packages/core/src/Field/index.ts (type exports)
 */

import {type CSSProperties, use} from 'react';
import type {StyleXStyles} from '@stylexjs/stylex';
import type {BaseProps} from '@astryxdesign/core/BaseProps';
import {FormLayoutContext} from '@astryxdesign/core/FormLayout';
import {useInputGroup} from '@astryxdesign/core/InputGroup';
import {useDevWarning} from '@astryxdesign/core/hooks';

/** Root styling props a Field-composed input does not accept. */
export type FieldInputForbiddenStyleProp = 'xstyle' | 'className' | 'style';

/** Styling for the Field box (label, control, and status together). */
// A prop mixin for Field-composed inputs, not a component props type.
// eslint-disable-next-line @astryx/require-base-props, @astryx/require-ref-prop
export interface FieldContainerStyleProps {
  /**
   * StyleX styles for the field container (the Field box around the label,
   * control, and status). Has no effect where no Field box renders: inside
   * InputGroup (style the InputGroup instead) and in a `horizontal-labels`
   * FormLayout.
   */
  containerXstyle?: StyleXStyles;
  /** Class name for the field container. Same targeting as `containerXstyle`. */
  containerClassName?: string;
  /** Inline styles for the field container. Same targeting as `containerXstyle`. */
  containerStyle?: CSSProperties;
}

/** Styling for the visual control box (border, background, icons, end controls). */
// A prop mixin for Field-composed inputs, not a component props type.
// eslint-disable-next-line @astryx/require-base-props, @astryx/require-ref-prop
export interface FieldControlStyleProps {
  /**
   * StyleX styles for the visual control box: the element that paints the
   * field border and background and holds its icons and end controls. Never
   * the native input.
   */
  controlXstyle?: StyleXStyles;
  /** Class name for the visual control box. */
  controlClassName?: string;
  /** Inline styles for the visual control box. */
  controlStyle?: CSSProperties;
}

export interface FieldPartStyleProps
  extends FieldContainerStyleProps, FieldControlStyleProps {}

/**
 * BaseProps for a Field-composed input. Root `xstyle`, `className`, and `style`
 * are omitted, so passing one is a type error; style the field through
 * `container*` and the control box through `control*`.
 */
export type FieldInputBaseProps<T extends HTMLElement = HTMLElement> = Omit<
  BaseProps<T>,
  FieldInputForbiddenStyleProp
> &
  FieldPartStyleProps;

/** Styling props to pass to Field's own `xstyle`/`className`/`style`. */
export interface FieldContainerTarget {
  xstyle?: StyleXStyles;
  className?: string;
  style?: CSSProperties;
}

export interface FieldInputStyling<R> {
  /** The caller's remaining props, with any untyped root styling removed. */
  rest: R;
  /**
   * Whether a Field box renders: false inside InputGroup and in a
   * `horizontal-labels` FormLayout, where Field lays out its children in the
   * form's columns without a box of its own.
   */
  hasFieldBox: boolean;
  /** Spread onto `<Field>`; empty where no Field box renders. */
  container: FieldContainerTarget;
}

const ROOT_STYLING_MESSAGE =
  '`xstyle`, `className`, and `style` are not supported on Field-composed inputs and were ignored. ' +
  'Style the field with `containerXstyle`/`containerClassName`/`containerStyle` and the control box with ' +
  '`controlXstyle`/`controlClassName`/`controlStyle`. `astryx upgrade` rewrites existing usage.';

const CONTAINER_WITHOUT_FIELD_MESSAGE =
  '`containerXstyle`/`containerClassName`/`containerStyle` have no effect here because no Field box renders ' +
  '(inside InputGroup or a `horizontal-labels` FormLayout). Inside InputGroup, style the InputGroup.';

/**
 * Resolve FR10 styling for a Field-composed input.
 *
 * Strips root `xstyle`/`className`/`style` that an untyped caller passed (they
 * would otherwise spread onto the native control) and warns once in
 * development. Returns the `container*` props to forward to Field only when a
 * Field box renders, and warns once when they are passed where none does.
 * `control*` props are the caller's to apply to the control box directly.
 *
 * @example
 * ```
 * const {rest, container} = useFieldInputStyling('TextInput', restProps, {
 *   containerXstyle, containerClassName, containerStyle,
 * });
 * ```
 */
export function useFieldInputStyling<R extends object>(
  component: string,
  restProps: R,
  containerProps: FieldContainerStyleProps,
): FieldInputStyling<R> {
  const inputGroup = useInputGroup();
  const {direction} = use(FormLayoutContext);
  const hasFieldBox = inputGroup == null && direction !== 'horizontal-labels';

  const untyped = restProps as R & {
    xstyle?: unknown;
    className?: unknown;
    style?: unknown;
  };
  const hasRootStyling =
    untyped.xstyle != null ||
    untyped.className != null ||
    untyped.style != null;
  let rest = restProps;
  if (hasRootStyling) {
    const {
      xstyle: _xstyle,
      className: _className,
      style: _style,
      ...remaining
    } = untyped;
    rest = remaining as R;
  }
  useDevWarning(component, ROOT_STYLING_MESSAGE, hasRootStyling);

  const {containerXstyle, containerClassName, containerStyle} = containerProps;
  const hasContainerStyling =
    containerXstyle != null ||
    containerClassName != null ||
    containerStyle != null;
  useDevWarning(
    component,
    CONTAINER_WITHOUT_FIELD_MESSAGE,
    hasContainerStyling && !hasFieldBox,
  );

  return {
    rest,
    hasFieldBox,
    container: hasFieldBox
      ? {
          xstyle: containerXstyle,
          className: containerClassName,
          style: containerStyle,
        }
      : {},
  };
}

// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file inputDisabledFocus.ts
 * @input Uses StyleX and theme tokens
 * @output inputDisabledFocusStyles (internal; not re-exported from Field/index.ts):
 *   the one place every field's disabled focus ring is defined
 * @position Field wrapper style shared by the text-entry fields
 */

import * as stylex from '@stylexjs/stylex';
import {colorVars} from '@astryxdesign/core/theme/tokens.stylex';

export const inputDisabledFocusStyles = stylex.create({
  // The shared disabled style drops the focus ring; restore it while the field's
  // own control, a direct child, has keyboard focus (`spec:AST-085` FR6), so a
  // focused status button keeps only its own outline.
  ring: {
    borderColor: {
      default: colorVars['--color-border-emphasized'],
      ':has(> [aria-disabled="true"]:focus-visible)': {
        default: colorVars['--color-accent'],
        // Forced colors repaint author borders in one system color and drop
        // the inset shadow; Highlight keeps the focused field visible.
        '@media (forced-colors: active)': 'Highlight',
      },
    },
    boxShadow: {
      default: 'none',
      ':has(> [aria-disabled="true"]:focus-visible)': `inset 0px 0px 0px 2px ${colorVars['--color-accent-muted']}`,
    },
  },
  // The same ring for a field whose input sits deeper than the wrapper's
  // direct children (Typeahead, Tokenizer). Keyed on the input itself, so a
  // focused token or status button keeps only its own outline.
  nestedRing: {
    borderColor: {
      default: colorVars['--color-border-emphasized'],
      ':has(input[aria-disabled="true"]:focus-visible)': {
        default: colorVars['--color-accent'],
        // Forced colors repaint author borders in one system color and drop
        // the inset shadow; Highlight keeps the focused field visible.
        '@media (forced-colors: active)': 'Highlight',
      },
    },
    boxShadow: {
      default: 'none',
      ':has(input[aria-disabled="true"]:focus-visible)': `inset 0px 0px 0px 2px ${colorVars['--color-accent-muted']}`,
    },
  },

  // The same ring for a field that restores it while focus is anywhere inside
  // it (TimeInput, DateRangeInput, DateTimeInput and their touch fields).
  withinRing: {
    borderColor: {
      default: colorVars['--color-border-emphasized'],
      ':focus-within': {
        default: colorVars['--color-accent'],
        // Forced colors repaint author borders in one system color and drop
        // the inset shadow; Highlight keeps the focused field visible.
        '@media (forced-colors: active)': 'Highlight',
      },
    },
    boxShadow: {
      default: 'none',
      ':focus-within': `inset 0px 0px 0px 2px ${colorVars['--color-accent-muted']}`,
    },
  },
  // The same ring for a field that restores it while its text input has focus
  // (DateInput and its native and touch fields).
  inputFocusRing: {
    borderColor: {
      default: colorVars['--color-border-emphasized'],
      ':has(input:focus)': {
        default: colorVars['--color-accent'],
        // Forced colors repaint author borders in one system color and drop
        // the inset shadow; Highlight keeps the focused field visible.
        '@media (forced-colors: active)': 'Highlight',
      },
    },
    boxShadow: {
      default: 'none',
      ':has(input:focus)': `inset 0px 0px 0px 2px ${colorVars['--color-accent-muted']}`,
    },
  },
});

// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file inputStyles.stylex.ts
 * @input Uses theme tokens (color, spacing, radius, shadow, transition)
 * @output Exports shared input wrapper appearance styles, and the text field
 *   timing that shows the focus look at once under a coarse pointer
 * @position Shared styles consumed by TextInput, TextArea, NumberInput, DateInput,
 *   TimeInput, Selector, Typeahead, and Tokenizer
 *
 * Centralizes the input wrapper appearance (borders, focus outlines, hover shadows,
 * disabled state, status variants) so all input components stay in sync.
 * Individual components layer their own overrides (padding, alignment, etc.)
 * via stylex.props composition.
 */

import * as stylex from '@stylexjs/stylex';
import {
  colorVars,
  spacingVars,
  radiusVars,
  shadowVars,
  durationVars,
  easeVars,
  borderVars,
} from '@astryxdesign/core/theme/tokens.stylex';

/**
 * Base wrapper styles shared by all input components.
 * Components apply these as a foundation and override specific properties
 * (e.g. padding, alignItems, gap) as needed.
 */
export const inputWrapperStyles = stylex.create({
  base: {
    boxSizing: 'border-box',
    position: 'relative',
    zIndex: 1,
    display: 'flex',
    alignItems: 'center',
    gap: spacingVars['--spacing-2'],
    paddingBlock: spacingVars['--spacing-1'],
    paddingInline: spacingVars['--spacing-2'],
    borderWidth: borderVars['--border-width'],
    borderStyle: 'solid',
    // Forced colors drop the inset shadow below and repaint author border
    // colors in one system color, so the field-focus treatment would vanish
    // there. A focused field's border takes the system Highlight color instead
    // (`spec:AST-020` FR1).
    borderColor: {
      default: colorVars['--color-border-emphasized'],
      ':focus-within': {
        default: colorVars['--color-accent'],
        '@media (forced-colors: active)': 'Highlight',
      },
    },
    '--_field-radius': radiusVars['--radius-element'],
    borderRadius: 'var(--_field-radius)',
    backgroundColor: colorVars['--color-background-surface'],
    transitionProperty: 'border-color, box-shadow',
    transitionDuration: {
      default: durationVars['--duration-fast'],
      '@media (prefers-reduced-motion: reduce)': '0s',
    },
    transitionTimingFunction: easeVars['--ease-standard'],
    boxShadow: {
      default: 'none',
      ':hover:not(:focus-within):where(:not(:disabled,[aria-disabled="true"]))':
        {
          '@media (hover: hover)': `inset 0px 0px 0px 2px color-mix(in srgb, ${colorVars['--color-border-emphasized']} 30%, transparent)`,
        },
      ':focus-within': `inset 0px 0px 0px 2px ${colorVars['--color-accent-muted']}`,
    },
    outline: 'none',
  },
  disabled: {
    cursor: 'default',
    opacity: 0.5,
    borderColor: colorVars['--color-border-emphasized'],
    // Suppress the base hover ring — a disabled control must not react to hover.
    boxShadow: 'none',
  },
  // Text fields apply this after `base`. A tap on one raises the keyboard,
  // and a fade would repaint the field on each frame of that rise.
  textField: {
    transitionDuration: {
      default: durationVars['--duration-fast'],
      '@media (prefers-reduced-motion: reduce)': '0s',
      '@media (pointer: coarse)': '0s',
    },
  },
});

/**
 * Status border colors for input wrappers.
 * Keyed by InputStatusType. Under forced colors a focused field's border is
 * Highlight, as in the base style, for wrappers that apply no status focus
 * style of their own (Selector, MultiSelector).
 */
export const inputStatusBorderStyles = stylex.create({
  warning: {
    borderColor: {
      default: colorVars['--color-border-warning'],
      ':focus-within': {
        default: colorVars['--color-border-warning'],
        '@media (forced-colors: active)': 'Highlight',
      },
    },
  },
  error: {
    borderColor: {
      default: colorVars['--color-border-error'],
      ':focus-within': {
        default: colorVars['--color-border-error'],
        '@media (forced-colors: active)': 'Highlight',
      },
    },
  },
  success: {
    borderColor: {
      default: colorVars['--color-border-success'],
      ':focus-within': {
        default: colorVars['--color-border-success'],
        '@media (forced-colors: active)': 'Highlight',
      },
    },
  },
});

/**
 * Status hover shadow styles for input wrappers.
 * Keyed by InputStatusType.
 */
export const inputStatusHoverShadowStyles = stylex.create({
  warning: {
    boxShadow: {
      default: 'none',
      ':hover:not(:focus-within):where(:not(:disabled,[aria-disabled="true"]))':
        {
          '@media (hover: hover)': shadowVars['--shadow-inset-warning'],
        },
    },
  },
  error: {
    boxShadow: {
      default: 'none',
      ':hover:not(:focus-within):where(:not(:disabled,[aria-disabled="true"]))':
        {
          '@media (hover: hover)': shadowVars['--shadow-inset-error'],
        },
    },
  },
  success: {
    boxShadow: {
      default: 'none',
      ':hover:not(:focus-within):where(:not(:disabled,[aria-disabled="true"]))':
        {
          '@media (hover: hover)': shadowVars['--shadow-inset-success'],
        },
    },
  },
});

/**
 * Status focus border styles using :focus-within. Under forced colors the
 * focused border is Highlight, as in the base style.
 * Used by input wrappers that contain a child input/textarea element.
 * Keyed by InputStatusType.
 */
export const inputStatusFocusWithinStyles = stylex.create({
  warning: {
    borderColor: {
      default: colorVars['--color-border-warning'],
      ':focus-within': {
        default: colorVars['--color-border-warning'],
        '@media (forced-colors: active)': 'Highlight',
      },
    },
  },
  error: {
    borderColor: {
      default: colorVars['--color-border-error'],
      ':focus-within': {
        default: colorVars['--color-border-error'],
        '@media (forced-colors: active)': 'Highlight',
      },
    },
  },
  success: {
    borderColor: {
      default: colorVars['--color-border-success'],
      ':focus-within': {
        default: colorVars['--color-border-success'],
        '@media (forced-colors: active)': 'Highlight',
      },
    },
  },
});

/**
 * Status focus border styles using :focus.
 * Used by components where the wrapper itself receives focus (e.g. Selector button).
 * Keyed by InputStatusType.
 */
export const inputStatusFocusStyles = stylex.create({
  warning: {
    borderColor: {
      default: colorVars['--color-border-warning'],
      ':focus': colorVars['--color-border-warning'],
    },
  },
  error: {
    borderColor: {
      default: colorVars['--color-border-error'],
      ':focus': colorVars['--color-border-error'],
    },
  },
  success: {
    borderColor: {
      default: colorVars['--color-border-success'],
      ':focus': colorVars['--color-border-success'],
    },
  },
});

// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file textEntryTraits.ts
 * @input The keyboard-trait props a text field accepts
 * @output EnterKeyHint, InputMode and AutoCapitalize (the package entry exports
 *   these), TextEntryTraitProps and textEntryTraitAttributes
 * @position Shared by TextInput, TextArea and the search inputs: the one place
 *   that says how a field tells a touch keyboard what it holds
 *
 * SYNC: When modified, update:
 * - /packages/core/src/TextInput/TextInput.tsx and TextInput.doc.mjs
 * - /packages/core/src/TextArea/TextArea.tsx and TextArea.doc.mjs
 * - /packages/core/src/Typeahead/BaseTypeahead.tsx, Field/PanelSearchInput.tsx
 *   and CommandPalette/CommandPaletteInput.tsx (the search inputs)
 * - /packages/core/src/Field/index.ts (type exports)
 */

/**
 * What the Return key of a touch keyboard says. iOS gives `done`, `go`,
 * `next`, `search` and `send` their own key (a glyph on iOS 26: a checkmark,
 * an arrow, a chevron, a magnifier, an up arrow); `enter` and `previous` keep
 * the plain Return key. Chrome on Android (Gboard) gives every value its own
 * key; with no hint, a single-line field's key reads Next while another field
 * follows and a multi-line field's keeps Return, and a `type="url"` field
 * shows Next instead of `go` while another field follows.
 */
export type EnterKeyHint =
  'enter' | 'done' | 'go' | 'next' | 'previous' | 'search' | 'send';

/**
 * Which touch keyboard a field asks for, by the HTML standard's `inputmode`
 * values. `numeric` brings up the number pad, and on iOS `search` brings up
 * the web-search keyboard (a period key and a Go key, whatever
 * `enterKeyHint` says).
 */
export type InputMode =
  'none' | 'text' | 'tel' | 'url' | 'email' | 'numeric' | 'decimal' | 'search';

/**
 * When a touch keyboard capitalizes as you type: `off` and `none` never,
 * `on` and `sentences` at the start of each sentence (the HTML standard names
 * each of these two states twice), `words` at the start of each word, and
 * `characters` every letter.
 */
export type AutoCapitalize =
  'off' | 'none' | 'on' | 'sentences' | 'words' | 'characters';

/**
 * Keyboard traits of a text field: a prop mixin for TextInput and TextArea,
 * not a component's props. A touch keyboard reads these traits from the
 * focused element. An absent prop renders no attribute, so the browser keeps
 * its own default (on iOS a field capitalizes sentences, except a URL field).
 */
export interface TextEntryTraitProps {
  /**
   * What the Return key of a touch keyboard says (the native `enterkeyhint`).
   * It only labels the key: what Enter does stays with the field's own
   * handlers.
   */
  enterKeyHint?: EnterKeyHint;
  /**
   * Which touch keyboard the field asks for (the native `inputmode`),
   * without changing what the field accepts.
   */
  inputMode?: InputMode;
  /**
   * When a touch keyboard capitalizes as you type (the native
   * `autocapitalize`).
   */
  autoCapitalize?: AutoCapitalize;
  /**
   * Whether a touch keyboard corrects words as you type (the native
   * `autocorrect`).
   */
  hasAutoCorrect?: boolean;
}

/** The native attributes the traits render as. */
export interface TextEntryTraitAttributes {
  enterKeyHint?: EnterKeyHint;
  inputMode?: InputMode;
  autoCapitalize?: AutoCapitalize;
  autoCorrect?: 'on' | 'off';
}

/**
 * Maps keyboard-trait props onto the native attributes for the editable
 * element. Absent props produce no attribute.
 *
 * @example
 * ```
 * <input {...textEntryTraitAttributes({enterKeyHint: 'search', hasAutoCorrect: false})} />
 * ```
 */
export function textEntryTraitAttributes({
  enterKeyHint,
  inputMode,
  autoCapitalize,
  hasAutoCorrect,
}: TextEntryTraitProps): TextEntryTraitAttributes {
  const attributes: TextEntryTraitAttributes = {};
  if (enterKeyHint != null) {
    attributes.enterKeyHint = enterKeyHint;
  }
  if (inputMode != null) {
    attributes.inputMode = inputMode;
  }
  if (autoCapitalize != null) {
    attributes.autoCapitalize = autoCapitalize;
  }
  if (hasAutoCorrect != null) {
    attributes.autoCorrect = hasAutoCorrect ? 'on' : 'off';
  }
  return attributes;
}

// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * @file TextArea.tsx
 * @input Uses React, useId, ChangeEvent, ClipboardEvent, FocusEvent, Field, Icon, Spinner,
 *   textEntryTraits (the touch-keyboard trait props)
 * @output Exports TextArea component, TextAreaProps, TextAreaStatus, TextAreaStatusType
 * @position Core implementation; consumed by index.ts, tested by TextArea.test.tsx
 *
 * SYNC: When modified, update these files to stay in sync:
 * - /packages/core/src/TextArea/TextArea.doc.mjs (props table, features, implementation notes)
 * - /packages/core/src/TextArea/TextArea.test.tsx (tests for new/changed behavior)
 * - /packages/core/src/TextArea/index.ts (exports if types change)
 * - /apps/storybook/stories/TextArea.stories.tsx (storybook stories)
 * - /packages/cli/assets/templates/blocks/components/TextArea/ (showcase blocks)
 */

import {
  useId,
  useOptimistic,
  useTransition,
  useRef,
  useCallback,
  useMemo,
  type ChangeEvent,
  type ClipboardEvent,
  type FocusEvent,
  type ReactNode,
} from 'react';
import * as stylex from '@stylexjs/stylex';
import {
  colorVars,
  spacingVars,
  typographyVars,
  typeScaleVars,
} from '@astryxdesign/core/theme/tokens.stylex';
import {Field} from '@astryxdesign/core/Field';
import {
  inputWrapperStyles,
  inputStatusBorderStyles,
  inputStatusHoverShadowStyles,
  inputStatusFocusWithinStyles,
} from '../Field/inputStyles.stylex';
import {Icon, renderIconSlot, type IconType} from '@astryxdesign/core/Icon';
import {isRenderable} from '@astryxdesign/core/utils';
import {withholdCallerHandlers} from '../utils/disabledInteraction';
import {Spinner} from '@astryxdesign/core/Spinner';
import {useTooltip} from '@astryxdesign/core/Tooltip';
import {mergeProps} from '@astryxdesign/core/utils';
import {joinAriaIDs} from '../utils/inputAria';
import type {BaseProps} from '@astryxdesign/core/BaseProps';
import type {FieldInputBaseProps} from '@astryxdesign/core/Field';
import {useFieldInputStyling} from '../Field/fieldParts';
import {inputDisabledFocusStyles} from '../Field/inputDisabledFocus';
import type {SizeValue} from '@astryxdesign/core/utils';
import {useInputContainer} from '@astryxdesign/core/hooks';
import {useInputStatusIcon} from '@astryxdesign/core/hooks';
import {useAnnounce} from '@astryxdesign/core/hooks';
import {useResolvedRequired} from '../hooks/useResolvedRequired';
import {useSize} from '@astryxdesign/core/SizeContext';
import {themeProps} from '@astryxdesign/core/utils';
import {characterCount} from '@astryxdesign/core/utils';
import {
  textEntryTraitAttributes,
  type TextEntryTraitProps,
} from '../Field/textEntryTraits';

import {useMergedRefs} from '@astryxdesign/core/hooks';
import {useBusyAnnouncement} from '../hooks/useBusyAnnouncement';
import type {FieldStatusPlacement} from '@astryxdesign/core/Field';
import {registerEnglishFallback} from '../i18n/englishFallback';
import {useComponentTranslator} from '../i18n/useComponentTranslator';
import english from '../i18n/generated-english/TextArea/TextArea.generated';

registerEnglishFallback(english);
const COUNTER_WARNING_THRESHOLD = 0.8;

const styles = stylex.create({
  // The wrapper is a bare positioning context. The <textarea> spans the full
  // container and carries its own internal padding; icons, status/spinner, and
  // the character counter are absolutely-positioned overlays anchored to the
  // container corners. This keeps the native resize grip in the true
  // bottom-right corner and lets the scrollbar represent the full input area.
  wrapper: {
    zIndex: 1,
    display: 'block',
    // Zero the shared wrapper inset with matching longhands, not the `padding`
    // shorthand: StyleX ranks longhands above shorthands regardless of merge
    // order, so a `padding: 0` shorthand loses to the base's
    // paddingBlock/paddingInline. The wrapper would keep a duplicate inset that
    // the <textarea>'s own padding then doubles — insetting the text and
    // pushing the native resize grip in from the corner.
    paddingBlock: 0,
    paddingInline: 0,
    // Internal inline padding for the textarea's text. Defined on the wrapper
    // so the counter (a sibling overlay) inherits the same value and stays
    // aligned with the text edge. Kept as an internal var so it can later be
    // driven by a theme "padding" translation without touching either child.
    '--_textarea-inline-padding': spacingVars['--spacing-2'],
  },
  textarea: {
    display: 'block',
    width: '100%',
    boxSizing: 'border-box',
    minWidth: 0,
    borderWidth: 0,
    borderStyle: 'none',
    // Base internal padding; overlays get their own reserved space below.
    paddingBlock: spacingVars['--spacing-1'],
